import assert from 'node:assert/strict';
import { Session } from './src/session.js';

const host = (queryFn) => ({ queryFn, timers: { schedule: (fn, delay) => setTimeout(fn, delay) } });

let offlineCalls = 0;
const offline = new Session(host(({ signal }) => { offlineCalls++; assert.equal(signal.aborted, false); return 'new'; }), { online: false });
const departed = offline.subscribe('stop:1', { networkMode: 'online' });
assert.equal(offline.snapshot('stop:1').fetchStatus, 'paused');
offline.unsubscribe(departed);
offline.online(true);
await Promise.resolve();
assert.equal(offlineCalls, 0);
assert.deepEqual(offline.snapshot('stop:1'), { status: 'pending', fetchStatus: 'idle', data: null });
offline.subscribe('stop:1', { networkMode: 'online' });
assert.equal(offlineCalls, 1);

let resolve;
const running = new Session(host(() => new Promise(done => { resolve = done; })));
const handle = running.subscribe('stop:2');
running.unsubscribe(handle);
resolve('cached');
await Promise.resolve();
assert.deepEqual(running.snapshot('stop:2'), { status: 'success', fetchStatus: 'idle', data: 'cached' });

let sharedCalls = 0;
const shared = new Session(host(() => { sharedCalls++; return new Promise(() => {}); }));
const first = shared.subscribe('stop:3');
const second = shared.subscribe('stop:3');
assert.equal(sharedCalls, 1);
shared.unsubscribe(first);
shared.unsubscribe(second);

let aborted = false;
const consumed = new Session(host(({ signal }) => { signal.addEventListener('abort', () => { aborted = true; }); return new Promise(() => {}); }));
const consumingHandle = consumed.subscribe('stop:4');
consumed.unsubscribe(consumingHandle);
assert.equal(aborted, true);

console.log('session behavior checks passed');
EOF
